#include <stddef.h>
#include <stdint.h>
int64_t fifocache(const int64_t *a,size_t n,uint8_t *out,size_t cap){if(!a||n<2||n>26)return -1;int64_t c=a[0],ops=a[1];if(c<1||c>6||ops<0||ops>8||n!=2+3*(size_t)ops)return -1;int64_t k[6],v[6];size_t z=0;int hits=0,miss=0,g=0;uint8_t q[8];for(size_t i=0;i<(size_t)ops;i++){int64_t op=a[2+3*i],key=a[3+3*i],val=a[4+3*i];if(key<0||key>15||(op!=0&&op!=1))return -1;if(op==0){if(val<0||val>255)return -1;size_t j=0;while(j<z&&k[j]!=key)j++;if(j<z){for(size_t t=j+1;t<z;t++){k[t-1]=k[t];v[t-1]=v[t];}z--;}if(z==(size_t)c){for(size_t t=1;t<z;t++){k[t-1]=k[t];v[t-1]=v[t];}z--;}k[z]=key;v[z++]=val;}else{if(val!=0)return -1;size_t j=0;while(j<z&&k[j]!=key)j++;if(j<z){hits++;q[g++]=(uint8_t)v[j];}else{miss++;q[g++]=255;}}}size_t need=4+g+2*z;if(!out||cap<need)return -2;out[0]=(uint8_t)hits;out[1]=(uint8_t)miss;out[2]=(uint8_t)z;out[3]=(uint8_t)g;for(size_t i=0;i<g;i++)out[4+i]=q[i];for(size_t i=0;i<z;i++){out[4+g+2*i]=(uint8_t)k[i];out[5+g+2*i]=(uint8_t)v[i];}return (int64_t)need;}
